import{_ as e,o as i,c as t,a3 as s}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"DNS 与 CDN","description":"","frontmatter":{"title":"DNS 与 CDN","outline":[2,3],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"frontend/guide/core/web/network/dns-cdn.md","filePath":"frontend/guide/core/web/network/dns-cdn.md","lastUpdated":1785217527000}'),l={name:"frontend/guide/core/web/network/dns-cdn.md"};function r(n,a,o,d,p,c){return i(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="dns-与-cdn" tabindex="-1">DNS 与 CDN <a class="header-anchor" href="#dns-与-cdn" aria-label="Permalink to &quot;DNS 与 CDN&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>浏览器访问 <code>https://www.example.com/app.js</code> 时，必须先找到可连接的网络地址。DNS 负责把域名及其相关信息组织成分层、可缓存的记录；CDN 则把内容和连接入口部署到多个边缘节点，让用户从更合适的位置访问。两者经常共同完成流量调度，但职责不同：DNS 回答“这个名字当前有哪些记录”，CDN 回答“请求到达边缘后由谁响应、是否回源以及如何缓存”。</p><p>本篇面向前端需要理解的解析链路、记录类型、TTL、边缘缓存、回源和排障。权威 DNS 运维、BGP 路由实现和特定云厂商配置不展开。</p><h2 id="_1-dns-命名模型" tabindex="-1">1. DNS 命名模型 <a class="header-anchor" href="#_1-dns-命名模型" aria-label="Permalink to &quot;1. DNS 命名模型&quot;">​</a></h2><h3 id="_1-1-域名层级" tabindex="-1">1.1 域名层级 <a class="header-anchor" href="#_1-1-域名层级" aria-label="Permalink to &quot;1.1 域名层级&quot;">​</a></h3><p>域名从右向左形成层级：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>www.shop.example.com.</span></span>\n<span class="line"><span>|   |    |       |</span></span>\n<span class="line"><span>主机 子域 注册域  顶级域</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>末尾的点表示 DNS 根，在日常 URL 中通常省略。<code>com</code>、<code>example.com</code> 与 <code>shop.example.com</code> 可以由不同权威区域负责。</p><p>“注册域”受公共后缀规则影响，不能总用最后两个标签判断，例如 <code>example.co.uk</code>。</p><h3 id="_1-2-zone" tabindex="-1">1.2 Zone <a class="header-anchor" href="#_1-2-zone" aria-label="Permalink to &quot;1.2 Zone&quot;">​</a></h3><p>区域（zone）是由一组权威服务器管理的 DNS 数据范围。区域可以在子域处委派：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>example.com       -&gt; 一组权威服务器</span></span>\n<span class="line"><span>api.example.com   -&gt; 另一组权威服务器</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>域名层级与管理边界相关，但不是每个标签都必须对应独立 zone。</p><h3 id="_1-3-resource-record" tabindex="-1">1.3 Resource Record <a class="header-anchor" href="#_1-3-resource-record" aria-label="Permalink to &quot;1.3 Resource Record&quot;">​</a></h3><p>DNS 响应由资源记录组成。记录包含名称、类型、值、TTL 和类等字段。同一名称同一类型可以形成记录集，例如多个 A 地址。</p><h3 id="_1-4-dns-不是-url-路由" tabindex="-1">1.4 DNS 不是 URL 路由 <a class="header-anchor" href="#_1-4-dns-不是-url-路由" aria-label="Permalink to &quot;1.4 DNS 不是 URL 路由&quot;">​</a></h3><p>DNS 只处理主机名，不读取 URL path：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://example.com/products</span></span>\n<span class="line"><span>https://example.com/account</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>两者在 DNS 层都是 <code>example.com</code>。路径路由由 CDN、反向代理或应用在 HTTP 层处理。</p><h2 id="_2-解析参与者" tabindex="-1">2. 解析参与者 <a class="header-anchor" href="#_2-解析参与者" aria-label="Permalink to &quot;2. 解析参与者&quot;">​</a></h2><h3 id="_2-1-stub-resolver" tabindex="-1">2.1 Stub Resolver <a class="header-anchor" href="#_2-1-stub-resolver" aria-label="Permalink to &quot;2.1 Stub Resolver&quot;">​</a></h3><p>应用通常把查询交给操作系统的 stub resolver，而不是自己从根服务器开始递归。浏览器也可能具有自己的缓存、异步解析器或加密 DNS 配置。</p><h3 id="_2-2-recursive-resolver" tabindex="-1">2.2 Recursive Resolver <a class="header-anchor" href="#_2-2-recursive-resolver" aria-label="Permalink to &quot;2.2 Recursive Resolver&quot;">​</a></h3><p>递归解析器代表客户端查找最终答案并缓存结果。它可能来自运营商、企业网络、路由器或公共 DNS 服务。</p><p>客户端查询常带 <code>RD</code>（recursion desired），递归解析器在完成查找后返回答案或错误。</p><h3 id="_2-3-root-server" tabindex="-1">2.3 Root Server <a class="header-anchor" href="#_2-3-root-server" aria-label="Permalink to &quot;2.3 Root Server&quot;">​</a></h3><p>根服务器不会保存所有站点 IP。它主要告诉解析器对应顶级域（如 <code>.com</code>）的权威服务器位置。</p><h3 id="_2-4-tld-server" tabindex="-1">2.4 TLD Server <a class="header-anchor" href="#_2-4-tld-server" aria-label="Permalink to &quot;2.4 TLD Server&quot;">​</a></h3><p>顶级域服务器返回注册域的委派信息，例如 <code>example.com</code> 的 NS 记录及必要的 glue address。</p><h3 id="_2-5-authoritative-server" tabindex="-1">2.5 Authoritative Server <a class="header-anchor" href="#_2-5-authoritative-server" aria-label="Permalink to &quot;2.5 Authoritative Server&quot;">​</a></h3><p>权威服务器负责某个 zone 的最终记录。它返回权威答案，但通常不替普通客户端递归查询其他域名。</p><h2 id="_3-一次名称解析" tabindex="-1">3. 一次名称解析 <a class="header-anchor" href="#_3-一次名称解析" aria-label="Permalink to &quot;3. 一次名称解析&quot;">​</a></h2><h3 id="_3-1-本地命中" tabindex="-1">3.1 本地命中 <a class="header-anchor" href="#_3-1-本地命中" aria-label="Permalink to &quot;3.1 本地命中&quot;">​</a></h3><p>查询可能依次被以下位置满足：</p><ul><li>应用或浏览器 DNS 缓存；</li><li>操作系统缓存和 hosts 文件；</li><li>本地网络缓存；</li><li>递归解析器缓存。</li></ul><p>命中时不会重复访问根、TLD 和权威服务器。不同浏览器、操作系统和解析器的本地缓存上限可能小于权威 TTL。</p><h3 id="_3-2-递归查询" tabindex="-1">3.2 递归查询 <a class="header-anchor" href="#_3-2-递归查询" aria-label="Permalink to &quot;3.2 递归查询&quot;">​</a></h3><p>当递归解析器没有可用缓存时，典型链路是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端 -&gt; 递归解析器</span></span>\n<span class="line"><span>             |</span></span>\n<span class="line"><span>             +-&gt; 根：.com 去哪里查？</span></span>\n<span class="line"><span>             +-&gt; .com：example.com 去哪里查？</span></span>\n<span class="line"><span>             +-&gt; example.com 权威：www 的 A/AAAA 是什么？</span></span>\n<span class="line"><span>客户端 &lt;- 递归解析器返回并缓存答案</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>权威服务器之间还可能通过 CNAME 让解析继续到另一个名称。</p><h3 id="_3-3-连接并不只选一个地址" tabindex="-1">3.3 连接并不只选一个地址 <a class="header-anchor" href="#_3-3-连接并不只选一个地址" aria-label="Permalink to &quot;3.3 连接并不只选一个地址&quot;">​</a></h3><p>一个名称可返回多个 A 和 AAAA 记录。客户端可能按 IPv6/IPv4 可用性、历史质量和竞速算法选择地址，CDN 也可能根据解析器位置或网络路由返回不同结果。</p><p><code>nslookup</code> 看到的第一条地址不一定是浏览器最终连接地址。应在 Network 面板的 Remote Address 或连接日志中确认。</p><h2 id="_4-常用记录类型" tabindex="-1">4. 常用记录类型 <a class="header-anchor" href="#_4-常用记录类型" aria-label="Permalink to &quot;4. 常用记录类型&quot;">​</a></h2><h3 id="_4-1-a-与-aaaa" tabindex="-1">4.1 <code>A</code> 与 <code>AAAA</code> <a class="header-anchor" href="#_4-1-a-与-aaaa" aria-label="Permalink to &quot;4.1 `A` 与 `AAAA`&quot;">​</a></h3><p><code>A</code> 映射 IPv4 地址，<code>AAAA</code> 映射 IPv6 地址：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>www.example.com. 300 IN A    192.0.2.10</span></span>\n<span class="line"><span>www.example.com. 300 IN AAAA 2001:db8::10</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>文档中的地址来自保留示例网段，不能作为真实服务地址。</p><h3 id="_4-2-cname" tabindex="-1">4.2 <code>CNAME</code> <a class="header-anchor" href="#_4-2-cname" aria-label="Permalink to &quot;4.2 `CNAME`&quot;">​</a></h3><p><code>CNAME</code> 把一个名称声明为另一个规范名称：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>static.example.com. 300 IN CNAME edge.cdn.example.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>解析器随后继续查询 <code>edge.cdn.example</code> 的地址。CNAME 所在名称通常不能再同时拥有 A、AAAA、MX 等其他普通数据。</p><h3 id="_4-3-zone-apex" tabindex="-1">4.3 Zone Apex <a class="header-anchor" href="#_4-3-zone-apex" aria-label="Permalink to &quot;4.3 Zone Apex&quot;">​</a></h3><p><code>example.com</code> 这样的区域顶点必须有 SOA 和 NS 等记录，因此不能按标准直接设为 CNAME。部分 DNS 服务提供 ALIAS、ANAME 或 CNAME flattening，这是供应商在权威端合成 A/AAAA 的扩展行为，不是标准 CNAME 语义。</p><h3 id="_4-4-ns-与-soa" tabindex="-1">4.4 <code>NS</code> 与 <code>SOA</code> <a class="header-anchor" href="#_4-4-ns-与-soa" aria-label="Permalink to &quot;4.4 `NS` 与 `SOA`&quot;">​</a></h3><p><code>NS</code> 声明区域的权威服务器。<code>SOA</code> 描述主要服务器、区域序列号和否定缓存等管理信息。修改普通 A 记录时也要确保多权威节点的数据同步。</p><h3 id="_4-5-txt-与-caa" tabindex="-1">4.5 <code>TXT</code> 与 <code>CAA</code> <a class="header-anchor" href="#_4-5-txt-与-caa" aria-label="Permalink to &quot;4.5 `TXT` 与 `CAA`&quot;">​</a></h3><p><code>TXT</code> 保存文本数据，常用于域名所有权、邮件安全等验证。前端部署经常会遇到平台要求添加 TXT 记录，但它不参与普通 HTTP 地址解析。</p><p><code>CAA</code> 可限制哪些证书机构被允许为域名签发证书。它影响证书签发流程，不决定浏览器是否信任已签发证书。</p><h3 id="_4-6-https-与-svcb" tabindex="-1">4.6 <code>HTTPS</code> 与 <code>SVCB</code> <a class="header-anchor" href="#_4-6-https-与-svcb" aria-label="Permalink to &quot;4.6 `HTTPS` 与 `SVCB`&quot;">​</a></h3><p>HTTPS/SVCB 记录可以提供替代服务端点、ALPN 和地址提示，帮助客户端发现 HTTP/3 等能力。它们属于较新的部署能力：</p><ul><li>客户端与解析链支持程度需要验证；</li><li>address hints 只是提示，不能替代权威 A/AAAA 数据；</li><li>错误参数可能造成新客户端失败而旧客户端正常。</li></ul><p>基础站点仍应保持 A/AAAA 或 CNAME 路径可用，并将 HTTPS 记录作为经过兼容性验证的优化。</p><h2 id="_5-ttl-与缓存" tabindex="-1">5. TTL 与缓存 <a class="header-anchor" href="#_5-ttl-与缓存" aria-label="Permalink to &quot;5. TTL 与缓存&quot;">​</a></h2><h3 id="_5-1-正向缓存" tabindex="-1">5.1 正向缓存 <a class="header-anchor" href="#_5-1-正向缓存" aria-label="Permalink to &quot;5.1 正向缓存&quot;">​</a></h3><p>每条记录的 TTL 表示递归解析器可缓存它的秒数：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>www.example.com. 300 IN A 192.0.2.10</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>理论上缓存 300 秒后需要重新查询。实际客户端可能设置最小、最大 TTL 或使用已有连接，因此改记录后不一定恰好 5 分钟全部切换。</p><h3 id="_5-2-否定缓存" tabindex="-1">5.2 否定缓存 <a class="header-anchor" href="#_5-2-否定缓存" aria-label="Permalink to &quot;5.2 否定缓存&quot;">​</a></h3><p><code>NXDOMAIN</code>（名称不存在）和“名称存在但没有该类型”等否定答案也能缓存。刚创建新子域却仍有用户失败，可能是此前的否定缓存尚未过期。</p><p>否定 TTL 通常由区域 SOA 参数与响应规则决定，不是新建记录上的 TTL。</p><h3 id="_5-3-修改前降低-ttl" tabindex="-1">5.3 修改前降低 TTL <a class="header-anchor" href="#_5-3-修改前降低-ttl" aria-label="Permalink to &quot;5.3 修改前降低 TTL&quot;">​</a></h3><p>若计划迁移地址，可以在旧记录仍稳定时提前降低 TTL，等待原有较长 TTL 消耗完，再切换地址。切换后确认稳定，再提高 TTL。</p><p>切换时才把一天 TTL 改成 60 秒，无法让已经缓存旧答案的解析器立即更新。</p><h3 id="_5-4-dns-传播-是什么" tabindex="-1">5.4 “DNS 传播”是什么 <a class="header-anchor" href="#_5-4-dns-传播-是什么" aria-label="Permalink to &quot;5.4 “DNS 传播”是什么&quot;">​</a></h3><p>DNS 修改通常不是把记录逐台推送到全球服务器，而是：</p><ol><li>权威数据更新或在多权威节点间同步；</li><li>各递归缓存中的旧答案按 TTL 逐渐过期；</li><li>浏览器、操作系统和连接池也逐步放弃旧状态。</li></ol><p>因此应区分权威节点不一致、委派错误和正常缓存未过期，不能统一归因于“还在传播”。</p><h2 id="_6-dns-传输与安全" tabindex="-1">6. DNS 传输与安全 <a class="header-anchor" href="#_6-dns-传输与安全" aria-label="Permalink to &quot;6. DNS 传输与安全&quot;">​</a></h2><h3 id="_6-1-udp-与-tcp" tabindex="-1">6.1 UDP 与 TCP <a class="header-anchor" href="#_6-1-udp-与-tcp" aria-label="Permalink to &quot;6.1 UDP 与 TCP&quot;">​</a></h3><p>传统 DNS 通常先用 UDP 53 端口查询；响应过大、被截断或执行区域传送等场景可使用 TCP。现代扩展允许通过 EDNS 承载更大 UDP 响应，但仍要处理分片与回退。</p><h3 id="_6-2-dot-与-doh" tabindex="-1">6.2 DoT 与 DoH <a class="header-anchor" href="#_6-2-dot-与-doh" aria-label="Permalink to &quot;6.2 DoT 与 DoH&quot;">​</a></h3><p>DNS over TLS（DoT）和 DNS over HTTPS（DoH）加密客户端到递归解析器这一段，减少本地网络窃听和篡改。</p><p>它们不隐藏递归解析器看到的查询，也不自动加密递归解析器到权威服务器的全部链路。解析得到地址后，HTTP 内容仍需要 HTTPS 保护。</p><h3 id="_6-3-dnssec" tabindex="-1">6.3 DNSSEC <a class="header-anchor" href="#_6-3-dnssec" aria-label="Permalink to &quot;6.3 DNSSEC&quot;">​</a></h3><p>DNSSEC 用签名建立从根到目标 zone 的数据真实性链，帮助验证“答案来自有权发布该区域数据的一方且未被篡改”。它不加密查询内容，也不证明目标网站业务可信。</p><p>配置错误的签名、DS 或密钥轮换可能让启用验证的解析器返回 <code>SERVFAIL</code>，而未验证环境仍看似正常。</p><h2 id="_7-cdn-的请求模型" tabindex="-1">7. CDN 的请求模型 <a class="header-anchor" href="#_7-cdn-的请求模型" aria-label="Permalink to &quot;7. CDN 的请求模型&quot;">​</a></h2><h3 id="_7-1-point-of-presence" tabindex="-1">7.1 Point of Presence <a class="header-anchor" href="#_7-1-point-of-presence" aria-label="Permalink to &quot;7.1 Point of Presence&quot;">​</a></h3><p>CDN 在多个网络位置部署 PoP（Point of Presence）。用户通常连接到网络上更合适的边缘节点，而不是直接访问源站。</p><p>“最近”不一定是地理距离最短。路由质量、运营商互联、容量、健康状态和成本都会影响选择。</p><h3 id="_7-2-流量调度" tabindex="-1">7.2 流量调度 <a class="header-anchor" href="#_7-2-流量调度" aria-label="Permalink to &quot;7.2 流量调度&quot;">​</a></h3><p>常见入口方式包括：</p><ul><li>DNS 返回不同边缘地址；</li><li>Anycast 让多个 PoP 宣告同一 IP，由网络路由选择入口；</li><li>CNAME 把业务子域交给 CDN 权威系统；</li><li>HTTPS/SVCB 或 <code>Alt-Svc</code> 提示替代协议端点。</li></ul><p>一个 CDN 可以组合多种方式，不能只看 CNAME 推断完整调度过程。</p><h3 id="_7-3-边缘处理" tabindex="-1">7.3 边缘处理 <a class="header-anchor" href="#_7-3-边缘处理" aria-label="Permalink to &quot;7.3 边缘处理&quot;">​</a></h3><p>请求到达边缘后，CDN依据 Host、路径、查询、请求字段和配置执行：</p><ol><li>TLS 终止并选择站点；</li><li>计算缓存键；</li><li>查找边缘缓存；</li><li>命中则直接响应；</li><li>未命中则连接源站；</li><li>根据响应字段与规则决定是否存储。</li></ol><p>重写、鉴权、边缘函数等能力是产品扩展，不是每个 CDN 都有的标准步骤。</p><h3 id="_7-4-origin" tabindex="-1">7.4 Origin <a class="header-anchor" href="#_7-4-origin" aria-label="Permalink to &quot;7.4 Origin&quot;">​</a></h3><p>源站是 CDN 未命中时获取内容的上游，可以是对象存储、负载均衡器或应用服务。源站应限制绕过 CDN 的访问，正确验证 CDN 到源站的 TLS，并保留必要的 Host。</p><h2 id="_8-cdn-缓存与回源" tabindex="-1">8. CDN 缓存与回源 <a class="header-anchor" href="#_8-cdn-缓存与回源" aria-label="Permalink to &quot;8. CDN 缓存与回源&quot;">​</a></h2><h3 id="_8-1-缓存键" tabindex="-1">8.1 缓存键 <a class="header-anchor" href="#_8-1-缓存键" aria-label="Permalink to &quot;8.1 缓存键&quot;">​</a></h3><p>最小缓存键通常包含 scheme、host、path 和 query，但具体产品可能忽略、排序或筛选查询参数。若响应随语言、编码或 Origin 变化，还要正确处理 <code>Vary</code> 或显式缓存键配置。</p><p>把所有 Cookie 都纳入键会极大降低命中率；完全忽略影响响应的 Cookie 又可能泄漏用户数据。</p><h3 id="_8-2-ttl-与源站指令" tabindex="-1">8.2 TTL 与源站指令 <a class="header-anchor" href="#_8-2-ttl-与源站指令" aria-label="Permalink to &quot;8.2 TTL 与源站指令&quot;">​</a></h3><p>CDN 可以尊重 <code>Cache-Control: s-maxage</code>、<code>max-age</code> 和 <code>Expires</code>，也可以由边缘规则覆盖。覆盖源站字段前必须明确谁拥有缓存策略，否则源站认为 <code>no-store</code>、CDN 却强制缓存会形成数据风险。</p><p>HTTP 字段的详细语义见“HTTP 缓存”。</p><h3 id="_8-3-revalidation" tabindex="-1">8.3 Revalidation <a class="header-anchor" href="#_8-3-revalidation" aria-label="Permalink to &quot;8.3 Revalidation&quot;">​</a></h3><p>边缘响应过期后可带 <code>If-None-Match</code> 或 <code>If-Modified-Since</code> 回源。源站返回 <code>304</code> 时，边缘继续使用已保存内容并更新元数据。</p><h3 id="_8-4-purge-与版本化" tabindex="-1">8.4 Purge 与版本化 <a class="header-anchor" href="#_8-4-purge-与版本化" aria-label="Permalink to &quot;8.4 Purge 与版本化&quot;">​</a></h3><p>CDN purge 可以按 URL、标签或全站清除缓存，能力和完成时间由供应商决定。发布静态资源时，内容哈希 URL 比依赖全局 purge 更可靠：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/assets/app.3b771c.js</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>新内容产生新 URL，旧 URL 保留到所有旧 HTML 退出使用。</p><h3 id="_8-5-origin-shield-与请求合并" tabindex="-1">8.5 Origin Shield 与请求合并 <a class="header-anchor" href="#_8-5-origin-shield-与请求合并" aria-label="Permalink to &quot;8.5 Origin Shield 与请求合并&quot;">​</a></h3><p>多层缓存或 origin shield 可让多个 PoP 先访问一个上层缓存，降低源站压力。请求合并则让大量相同未命中只触发一次回源。</p><p>这两种能力均依赖 CDN 产品和配置。它们降低重复回源，不会修复错误缓存键或不可缓存响应。</p><h2 id="_9-动态与个性化内容" tabindex="-1">9. 动态与个性化内容 <a class="header-anchor" href="#_9-动态与个性化内容" aria-label="Permalink to &quot;9. 动态与个性化内容&quot;">​</a></h2><h3 id="_9-1-公共动态数据" tabindex="-1">9.1 公共动态数据 <a class="header-anchor" href="#_9-1-公共动态数据" aria-label="Permalink to &quot;9.1 公共动态数据&quot;">​</a></h3><p>商品分类、公共配置和匿名榜单可使用短 TTL、<code>s-maxage</code> 和 stale 策略缓存。必须声明容许陈旧时间，并确认不同地区、语言或实验组是否需要不同变体。</p><h3 id="_9-2-用户数据" tabindex="-1">9.2 用户数据 <a class="header-anchor" href="#_9-2-用户数据" aria-label="Permalink to &quot;9.2 用户数据&quot;">​</a></h3><p>账户、权限、订单等内容默认不应进入共享缓存：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> private, no-store</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>若边缘需要做用户级缓存，必须把经过验证的用户身份纳入隔离键，并评估注销、权限变更和缓存清除。它已超出普通公共 CDN 缓存的安全范围。</p><h3 id="_9-3-缓存欺骗与投毒" tabindex="-1">9.3 缓存欺骗与投毒 <a class="header-anchor" href="#_9-3-缓存欺骗与投毒" aria-label="Permalink to &quot;9.3 缓存欺骗与投毒&quot;">​</a></h3><p>攻击者可能构造看似静态的路径、异常 Host、未纳入缓存键的请求字段或可控响应，诱导共享缓存保存错误内容。防护包括：</p><ul><li>只缓存明确允许的状态、路径和内容类型；</li><li>规范化并校验 Host 与路径；</li><li>让影响响应的输入进入缓存键或禁止缓存；</li><li>不缓存带用户会话的响应；</li><li>监控缓存命中响应的 <code>Age</code>、key 和来源。</li></ul><h2 id="_10-tls-与域名边界" tabindex="-1">10. TLS 与域名边界 <a class="header-anchor" href="#_10-tls-与域名边界" aria-label="Permalink to &quot;10. TLS 与域名边界&quot;">​</a></h2><h3 id="_10-1-边缘证书" tabindex="-1">10.1 边缘证书 <a class="header-anchor" href="#_10-1-边缘证书" aria-label="Permalink to &quot;10.1 边缘证书&quot;">​</a></h3><p>浏览器与 CDN 边缘建立 TLS。边缘证书必须覆盖用户访问的自定义域名，DNS 指到 CDN 并不会自动让证书有效。</p><h3 id="_10-2-源站证书" tabindex="-1">10.2 源站证书 <a class="header-anchor" href="#_10-2-源站证书" aria-label="Permalink to &quot;10.2 源站证书&quot;">​</a></h3><p>CDN 回源使用的主机名可能与公开域名不同。应明确回源 SNI、Host 和证书验证名称，不能仅开启“HTTPS 回源”却忽略证书错误。</p><h3 id="_10-3-cname-不改变浏览器-url" tabindex="-1">10.3 CNAME 不改变浏览器 URL <a class="header-anchor" href="#_10-3-cname-不改变浏览器-url" aria-label="Permalink to &quot;10.3 CNAME 不改变浏览器 URL&quot;">​</a></h3><p><code>static.example.com CNAME edge.cdn.example</code> 只影响解析。浏览器地址、HTTP Host 与 TLS SNI 仍是 <code>static.example.com</code>，因此边缘必须配置这个业务域名。</p><h2 id="_11-诊断-dns" tabindex="-1">11. 诊断 DNS <a class="header-anchor" href="#_11-诊断-dns" aria-label="Permalink to &quot;11. 诊断 DNS&quot;">​</a></h2><h3 id="_11-1-查询指定类型" tabindex="-1">11.1 查询指定类型 <a class="header-anchor" href="#_11-1-查询指定类型" aria-label="Permalink to &quot;11.1 查询指定类型&quot;">​</a></h3><p>Windows 可使用：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Resolve-DnsName</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> www.example.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Type A</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Resolve-DnsName</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> www.example.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Type AAAA</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Resolve-DnsName</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> static.example.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Type CNAME</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>通用环境也可使用：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nslookup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -type=A</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> www.example.com</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>比较记录值、TTL、返回服务器和错误类型。命令输出格式随系统实现不同。</p><h3 id="_11-2-查询不同解析器" tabindex="-1">11.2 查询不同解析器 <a class="header-anchor" href="#_11-2-查询不同解析器" aria-label="Permalink to &quot;11.2 查询不同解析器&quot;">​</a></h3><p>若只有某地区或网络异常，分别检查：</p><ul><li>权威服务器直接答案；</li><li>受影响网络的递归解析器；</li><li>一个独立公共解析器；</li><li>浏览器实际使用的 DoH 解析器。</li></ul><p>“公共 DNS 已更新”不能证明所有权威节点一致，也不能证明用户浏览器没有旧缓存。</p><h3 id="_11-3-错误分类" tabindex="-1">11.3 错误分类 <a class="header-anchor" href="#_11-3-错误分类" aria-label="Permalink to &quot;11.3 错误分类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>结果</th><th>含义与优先检查</th></tr></thead><tbody><tr><td><code>NXDOMAIN</code></td><td>名称不存在；检查拼写、zone 与否定缓存</td></tr><tr><td><code>NOERROR</code> 但无目标类型</td><td>名称存在但没有所查记录</td></tr><tr><td><code>SERVFAIL</code></td><td>解析器无法给出有效答案；检查 DNSSEC、权威可达性</td></tr><tr><td><code>REFUSED</code></td><td>服务器拒绝该类查询或客户端</td></tr><tr><td>超时</td><td>网络、53 端口、权威容量或包大小问题</td></tr></tbody></table><h2 id="_12-诊断-cdn" tabindex="-1">12. 诊断 CDN <a class="header-anchor" href="#_12-诊断-cdn" aria-label="Permalink to &quot;12. 诊断 CDN&quot;">​</a></h2><h3 id="_12-1-先区分解析与-http" tabindex="-1">12.1 先区分解析与 HTTP <a class="header-anchor" href="#_12-1-先区分解析与-http" aria-label="Permalink to &quot;12.1 先区分解析与 HTTP&quot;">​</a></h3><p>DNS 成功只说明获得了候选地址。继续在 Network 面板确认：</p><ul><li>Remote Address 是否是预期边缘；</li><li>TLS 证书是否覆盖业务域名；</li><li>状态码来自边缘还是源站；</li><li><code>Age</code>、<code>Cache-Control</code>、<code>ETag</code> 与供应商缓存字段；</li><li>同 URL 多次请求的命中状态；</li><li>请求 Host、query 和影响变体的字段。</li></ul><h3 id="_12-2-单地区旧资源案例" tabindex="-1">12.2 单地区旧资源案例 <a class="header-anchor" href="#_12-2-单地区旧资源案例" aria-label="Permalink to &quot;12.2 单地区旧资源案例&quot;">​</a></h3><p>症状：新版本发布后，某地区仍加载旧 JavaScript。</p><p>错误做法是立即归因于“DNS 没传播”。DNS 只决定去哪个边缘；旧内容也可能来自浏览器、Service Worker 或 CDN 缓存。</p><p>按证据排查：</p><ol><li>HTML 中引用的是旧 URL，还是新哈希 URL；</li><li>请求是否由 Service Worker 或浏览器 cache 返回；</li><li>Remote Address 是否属于预期 CDN；</li><li>响应 <code>Age</code> 和 CDN 命中字段是否显示旧边缘对象；</li><li>不同地区对同一 URL 的 ETag 和内容哈希是否一致；</li><li>源站是否仍能返回旧文件。</li></ol><p>假设结果如下：</p><table tabindex="0"><thead><tr><th>证据</th><th>结果</th></tr></thead><tbody><tr><td>HTML 引用</td><td>新 URL <code>app.7c1.js</code></td></tr><tr><td>浏览器 / Service Worker</td><td>均未命中</td></tr><tr><td>DNS 与 Remote Address</td><td>到达预期 CDN</td></tr><tr><td>受影响地区 <code>Age</code></td><td>4200 秒</td></tr><tr><td>其他地区</td><td>新内容，<code>Age: 30</code></td></tr><tr><td>源站</td><td>新内容</td></tr></tbody></table><p>结论：是 CDN 区域缓存对象未被正确版本化或清除，不是 DNS 故障。修复当前对象后，还应让文件名严格包含内容哈希，发布流程校验“同 URL 内容不可变”。</p><h3 id="_12-3-回源激增" tabindex="-1">12.3 回源激增 <a class="header-anchor" href="#_12-3-回源激增" aria-label="Permalink to &quot;12.3 回源激增&quot;">​</a></h3><p>命中率突然下降时检查：</p><ul><li>新增 Cookie 或 <code>Vary</code> 是否扩大缓存键；</li><li>查询参数是否出现随机值；</li><li>源站是否误发 <code>private</code> / <code>no-store</code>；</li><li>状态码或内容类型是否不再可缓存；</li><li>purge 是否清除了大范围资源；</li><li>同一热点对象是否缺乏请求合并。</li></ul><p>只扩容源站会缓解症状，不会恢复缓存键和策略。</p><h2 id="_13-常见误区" tabindex="-1">13. 常见误区 <a class="header-anchor" href="#_13-常见误区" aria-label="Permalink to &quot;13. 常见误区&quot;">​</a></h2><h3 id="_13-1-dns-把域名解析成唯一-ip" tabindex="-1">13.1 “DNS 把域名解析成唯一 IP” <a class="header-anchor" href="#_13-1-dns-把域名解析成唯一-ip" aria-label="Permalink to &quot;13.1 “DNS 把域名解析成唯一 IP”&quot;">​</a></h3><p>一个名称可以有多个 IPv4/IPv6 地址，答案还可能因解析器、地区和时间变化。</p><h3 id="_13-2-ttl-是修改后开始倒计时" tabindex="-1">13.2 “TTL 是修改后开始倒计时” <a class="header-anchor" href="#_13-2-ttl-是修改后开始倒计时" aria-label="Permalink to &quot;13.2 “TTL 是修改后开始倒计时”&quot;">​</a></h3><p>每个缓存从它取得旧答案时开始计算 TTL。修改权威记录不会重置或清除外部已有缓存。</p><h3 id="_13-3-cname-是-http-重定向" tabindex="-1">13.3 “CNAME 是 HTTP 重定向” <a class="header-anchor" href="#_13-3-cname-是-http-重定向" aria-label="Permalink to &quot;13.3 “CNAME 是 HTTP 重定向”&quot;">​</a></h3><p>CNAME 只影响名称解析，浏览器 URL 不变，也不会收到 3xx 响应。</p><h3 id="_13-4-用了-cdn-就不会访问源站" tabindex="-1">13.4 “用了 CDN 就不会访问源站” <a class="header-anchor" href="#_13-4-用了-cdn-就不会访问源站" aria-label="Permalink to &quot;13.4 “用了 CDN 就不会访问源站”&quot;">​</a></h3><p>未命中、过期验证、不可缓存、purge 和动态请求仍会回源。CDN 故障切换也可能改变路径。</p><h3 id="_13-5-cdn-一定让所有用户更快" tabindex="-1">13.5 “CDN 一定让所有用户更快” <a class="header-anchor" href="#_13-5-cdn-一定让所有用户更快" aria-label="Permalink to &quot;13.5 “CDN 一定让所有用户更快”&quot;">​</a></h3><p>错误路由、差的运营商互联、低命中率、额外 TLS 终止或边缘处理都可能增加延迟。需要按地区观察 DNS、连接、TTFB、命中率和回源时间。</p><h2 id="_14-总结" tabindex="-1">14. 总结 <a class="header-anchor" href="#_14-总结" aria-label="Permalink to &quot;14. 总结&quot;">​</a></h2><ul><li>DNS 是分层、委派且可缓存的命名系统；递归解析器代表客户端从根、TLD 和权威链路获得答案。</li><li>A/AAAA 提供地址，CNAME 提供名称别名，NS/SOA 描述权威区域；HTTPS/SVCB 是需要兼容性验证的进阶服务绑定能力。</li><li>TTL 控制旧答案可缓存多久，不是全球推送完成时间；否定答案同样可能被缓存。</li><li>CDN 通过 DNS、Anycast 等方式把流量引向边缘，再按缓存键决定命中、验证或回源。</li><li>前端排障必须把 DNS、浏览器缓存、Service Worker、CDN 缓存、TLS 和源站分层取证，不能用“解析正常”或“已清 CDN”代替完整结论。</li></ul><h2 id="_15-参考资料" tabindex="-1">15. 参考资料 <a class="header-anchor" href="#_15-参考资料" aria-label="Permalink to &quot;15. 参考资料&quot;">​</a></h2><ul><li><a href="https://www.rfc-editor.org/rfc/rfc1034" target="_blank" rel="noreferrer">RFC 1034: Domain Names - Concepts and Facilities</a></li><li><a href="https://www.rfc-editor.org/rfc/rfc1035" target="_blank" rel="noreferrer">RFC 1035: Domain Names - Implementation and Specification</a></li><li><a href="https://www.rfc-editor.org/rfc/rfc2308" target="_blank" rel="noreferrer">RFC 2308: Negative Caching of DNS Queries</a></li><li><a href="https://www.rfc-editor.org/rfc/rfc4033" target="_blank" rel="noreferrer">RFC 4033: DNS Security Introduction and Requirements</a></li><li><a href="https://www.rfc-editor.org/rfc/rfc9460" target="_blank" rel="noreferrer">RFC 9460: Service Binding and Parameter Specification via SVCB and HTTPS Records</a></li><li><a href="https://developer.mozilla.org/en-US/docs/Learn_web_development/Howto/Web_mechanics/How_does_the_Internet_work" target="_blank" rel="noreferrer">MDN: How does the Internet work?</a></li></ul>',179)])])}const b=e(l,[["render",r]]);export{u as __pageData,b as default};
